from itertools import combinations


def _route(minimum, exact):
    def solve(data):
        required = data.get("required", [])
        full = (1 << len(required)) - 1
        visit = {node: sum(1 << i for i, name in enumerate(required) if name == node)
                 for node in range(data["n"])}
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        start_state = (source, visit[source], 0)
        best = {start_state: data["start"]}
        queue = [(data["start"], source, visit[source], 0)]
        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if best.get(state) != time:
                continue
            if (node == data["target"] and mask == full and
                    (used == data["coupons"] if exact else used <= data["coupons"])):
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                durations = [edge["duration"]]
                if used < data["coupons"]:
                    durations.append(max(minimum, edge["duration"] - edge.get("discount", 0)))
                for option, duration in enumerate(durations):
                    next_used = used + (option == 1)
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    next_state = (nxt, mask | visit[nxt], next_used)
                    if arrival < best.get(next_state, float("inf")):
                        best[next_state] = arrival
                        heapq.heappush(queue, (arrival, nxt, mask | visit[nxt], next_used))
        return {"arrival": None}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "floor":
            return numerator // 10000
        return (2 * numerator + 10000) // 20000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = {}
    for name in names:
        choices[name] = [row for row in packages[name]
                         if row["version"] not in blocked.get(name, [])
                         and (name not in pins or row["version"] == pins[name])]

    best_vector = None
    best_result = None
    # Enumerate the small bounded version space; absent is a genuine option.
    def check(selection):
        installed = set(selection)
        if any(name not in installed or not lo <= selection[name] <= hi
               for name, (lo, hi) in roots.items()):
            return False
        graph = {name: [] for name in installed}
        for name, version in selection.items():
            row = next((r for r in packages[name] if r["version"] == version), None)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                if other not in installed or not dep["min"] <= selection[other] <= dep["max"]:
                    return False
                graph[name].append(other)
        # Installed packages must be exactly the active closure of the roots.
        reached = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reached:
                continue
            if name not in installed:
                return False
            reached.add(name)
            stack.extend(graph[name])
        if reached != installed:
            return False
        active, finished = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        return all(visit(name) for name in installed)

    def search(index, selection):
        nonlocal best_vector, best_result
        if index == len(names):
            if check(selection):
                vector = tuple(selection.get(name, -1) for name in names)
                if best_vector is None or vector < best_vector:
                    best_vector = vector
                    best_result = dict(selection)
            return
        name = names[index]
        search(index + 1, selection)
        for row in choices[name]:
            selection[name] = row["version"]
            search(index + 1, selection)
        selection.pop(name, None)

    search(0, {})
    return {"versions": best_result} if best_result is not None else {"error": "unsatisfiable"}


def _jobs(data):
    jobs = [job for job in data["jobs"] if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        selected = sorted(ids)
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


